#include <cstring>

using namespace std;

int n, m;
int total;

// Directions: 0=stay, 1=up, 2=down, 3=left, 4=right
int dx[5] = {0, -1, 1, 0, 0};
int dy[5] = {0, 0, 0, -1, 1};

// For each cell (i,j), store which commands are valid
vector<vector<int>> valid_commands;

int main() {
    cin >> n >> m;
    total = n * m;

    valid_commands.resize(n * m);

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            int idx = i * m + j;
            // Stay is always valid
            valid_commands[idx].push_back(0);
            // Up
            if (i > 0) valid_commands[idx].push_back(1);
            // Down
            if (i < n - 1) valid_commands[idx].push_back(2);
            // Left
            if (j > 0) valid_commands[idx].push_back(3);
            // Right
            if (j < m - 1) valid_commands[idx].push_back(4);
        }
    }

    // We need to assign a command to each cell such that no two spiders end up in the same cell
    // This is a bipartite matching problem: left side = cells (spiders), right side = cells (destination)
    // Edge from spider at cell u to destination cell v if there's a valid command for spider u that moves it to v

    // Build adjacency list for bipartite matching
    // Left: n*m spiders, Right: n*m destinations
    vector<vector<int>> adj(total);

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            int u = i * m + j;
            for (int cmd : valid_commands[u]) {
                int ni = i + dx[cmd];
                int nj = j + dy[cmd];
                int v = ni * m + nj;
                adj[u].push_back(v);
            }
        }
    }

    // Hopcroft-Karp or simple DFS-based bipartite matching
    // Since total <= 40, simple DFS is fine

    vector<int> matchR(total, -1); // matchR[v] = u, which spider is matched to destination v

    bool dfs(int u, vector<bool>& visited) {
        for (int v : adj[u]) {
            if (visited[v]) continue;
            visited[v] = true;
            if (matchR[v] == -1 || dfs(matchR[v], visited)) {
                matchR[v] = u;
                return true;
            }
        }
        return false;
    }

    int max_matching = 0;
    for (int u = 0; u < total; u++) {
        vector<bool> visited(total, false);
        if (dfs(u, visited)) {
            max_matching++;
        }
    }

    // The number of occupied cells is max_matching (each matched spider occupies a unique cell)
    // The number of empty cells is total - max_matching
    cout << total - max_matching << endl;

    return 0;
}
